{
  "slug": "check-tally-voucher-after-sync",
  "title": "How to Check a Tally Voucher After Syncing to Your Phone",
  "description": "Verify a mobile voucher by matching the company, financial year, type, number, party and amount with TallyPrime.",
  "category": "Vouchers and Day Book",
  "sections": [
    {
      "heading": "Record the original voucher",
      "body": "Open the correct company in TallyPrime. Note the voucher date, type, number, party and amount. Write down all six details including the company, since the number can be repeated in a different company, type or year."
    },
    {
      "heading": "Look up that exact entry in Syncora",
      "body": "Select the same company and financial year. Include the voucher date in your filter and use Day Book or Vouchers to find the entry. If the number appears twice, use the type and party to separate the two results."
    },
    {
      "heading": "Compare after a successful run",
      "body": "Check when the connector last succeeded. An edit in TallyPrime that happened later may still be pending. If the amount differs after a successful run, record the original and synced values and give support the voucher details and sync time."
    }
  ],
  "relatedPaths": [
    "/guides/tally-sync-troubleshooting",
    "/product-overview"
  ]
}
